Real Thing::getHeightAboveTerrain() const
{
	// Retail tests bit 2 of +0x5C, fills +0x54 through the virtual on a miss, then sets the bit.
	if (!(m_cacheValidBits & CACHED_GROUND_CLEARANCE))
	{
		Real clearance = calculateHeightAboveTerrain();
		m_groundClearanceCache = clearance;
		m_cacheValidBits |= CACHED_GROUND_CLEARANCE;
	}
	return m_groundClearanceCache;
}

