// FUNCTION: BFME2 0x0030A4AC size=36 name=?calculateHeightAboveTerrain@Thing@@MBEMXZ evidence=N:ledger tier=A
Real Thing::calculateHeightAboveTerrain() const
{
	const Coord3D *where = getPosition();
	Real ground = TheTerrainLogic->getGroundHeight(where->x, where->y);
	return where->z - ground;
}

// FUNCTION: BFME2 0x0030A4D0 size=88 name=?getHeightAboveTerrainOrWater@Thing@@QBEMXZ evidence=N:ledger tier=A
Real Thing::getHeightAboveTerrainOrWater() const
{
	if ((m_cacheValidBits & CACHED_SURFACE_CLEARANCE) == 0)
	{
		const Coord3D *where = getPosition();
		Real surface;
		if (TheTerrainLogic->isUnderwater(where->x, where->y, &surface, NULL, NULL))
			m_surfaceClearanceCache = where->z - surface;
		else
			m_surfaceClearanceCache = getHeightAboveTerrain();
		m_cacheValidBits |= CACHED_SURFACE_CLEARANCE;
	}
	return m_surfaceClearanceCache;
}

// FUNCTION: BFME2 0x0030A528 size=746 name=?convertBonePosToWorldPos@Thing@@QBEXPBVCoord3D@@PBVMatrix3D@@PAU2@PAV3@@Z evidence=X:retail PE exports class Coord3D: ??0Matrix4D@@QAE@ABVCoord3D@@@Z tier=A

// FUNCTION: BFME2 0x0030A812 size=191 name=?transformPoint@Thing@@QAEXPBVCoord3D@@PAU2@@Z evidence=X:retail PE exports class Coord3D: ??0Matrix4D@@QAE@ABVCoord3D@@@Z tier=A
void Thing::transformPoint(const Coord3D *in, Coord3D *out)
{
	if (in == NULL || out == NULL)
		return;

	Vector3 vectorIn;
	Vector3 vectorOut;
	vectorIn.X = in->x;
	vectorIn.Y = in->y;
	vectorIn.Z = in->z;

	m_transform.Transform_Vector(m_transform, vectorIn, &vectorOut);

	out->x = vectorOut.X;
	out->y = vectorOut.Y;
	out->z = vectorOut.Z;
}

// FUNCTION: BFME2 0x0030A8EE size=62 name=?getUnitDirectionVector3D@Thing@@QBEXAAVCoord3D@@@Z evidence=X:retail PE exports class Coord3D: ??0Matrix4D@@QAE@ABVCoord3D@@@Z tier=A
void Thing::getUnitDirectionVector3D(Coord3D &dir) const
{
	Coord3D vdir;
	vdir.x = m_transform.Row[0][0];
	vdir.y = m_transform.Row[1][0];
	vdir.z = m_transform.Row[2][0];
	dir = vdir;
	dir.Normalize();
}

// FUNCTION: BFME2 0x0030A92C size=340 name=?setPositionZ@Thing@@QAEXM@Z evidence=N:ledger tier=A
void Thing::setPositionZ( Real z )
{
	if( !m_template->isKindOf( KINDOF_STICK_TO_TERRAIN_SLOPE) )
	{
		Real oldAngle = m_cachedAngle;
		Coord3D oldPos = m_cachedPos;
		Matrix3D oldMtx = m_transform;

		m_transform.Set_Z_Translation( z );
		m_cachedPos.z = z;

		if (m_cacheValidBits & CACHED_GROUND_CLEARANCE)
		{
			m_groundClearanceCache += (z - oldPos.z);
		}
		if (m_cacheValidBits & CACHED_SURFACE_CLEARANCE)
		{
			m_surfaceClearanceCache += (z - oldPos.z);
		}

		reactToTransformChange(&oldMtx, &oldPos, oldAngle);
	}
	else
	{
		Matrix3D mtx;
		const Bool stickToGround = true;	// yes, set the "z" pos
		Coord3D pos = m_cachedPos;
		pos.z = z;
		TheTerrainLogic->alignOnTerrain(getOrientation(), pos, stickToGround, mtx );
		setTransformMatrix(&mtx);
	}
}

